INSERT INTO `service` (`token`, `service_name`, `service_img`, `short_description`, `description`, `card1_title`, `card1_description`, `card2_title`, `card2_description`, `process_steps`, `faqs`, `status`, `delete_status`, `created_by`, `created_at`) VALUES ('annual-maintenance-contract', 'Annual Maintenance Contract (AMC) Service', 'themes/images/service-image-13.jpg', 'Keep your batteries and supported equipment in reliable working condition with our Annual Maintenance Contract (AMC) service. Get scheduled inspections, preventive maintenance, and technical support to help reduce unexpected breakdowns and improve operational reliability.', 'Regular maintenance plays an important role in extending equipment life, maintaining performance, and reducing unexpected service interruptions. Our Annual Maintenance Contract (AMC) service provides a structured maintenance plan for compatible battery systems, generators, and related equipment based on your operational requirements.\n\nThrough scheduled inspections and preventive maintenance, we help identify potential issues before they lead to major disruptions. Our AMC service may include battery health checks, terminal and connection inspections, genset battery maintenance, lithium-ion battery assessments, jump-start system checks, and general equipment condition reviews, depending on the agreed service scope.\n\nWhether you manage a commercial facility, industrial site, office, vehicle fleet, or backup power system, an annual maintenance plan helps organise routine servicing and maintenance activities. Our team assesses your equipment requirements and recommends a suitable maintenance schedule to support consistent operation.\n\nChoose an Annual Maintenance Contract tailored to your equipment, usage, and service needs. With planned maintenance and professional technical assistance, you can manage maintenance requirements more effectively and keep your supported equipment ready for use.', 'Scheduled Preventive Maintenance', 'Keep your equipment regularly inspected through planned maintenance visits. Our service helps identify battery performance issues, loose connections, visible wear, and other maintenance concerns before they develop into more significant problems.', 'Reliable Technical Support', 'Get maintenance guidance and technical assistance according to your AMC agreement. Our team helps assess equipment issues, recommend suitable corrective actions, and plan the required service to support reliable day-to-day operations.', 'Service Enquiry - Contact our team and share your annual maintenance requirements.\nEquipment Assessment - Provide details about your batteries, generators, vehicles, or other supported equipment.\nAMC Plan Recommendation - We assess your requirements and recommend a suitable maintenance plan and service scope.\nContract Confirmation - Confirm the maintenance schedule, service coverage, contract duration, and applicable charges.\nScheduled Maintenance - Carry out planned inspections and preventive maintenance according to the agreed schedule.\nIssue Identification - Document identified concerns and recommend corrective maintenance or replacement where necessary.\nService Reporting - Provide maintenance updates and recommendations based on the work performed.\nAnnual Review - Review equipment condition and upcoming maintenance requirements before the contract renewal, where applicable.', '[{\"question\":\"What is an Annual Maintenance Contract (AMC)?\",\"answer\":\"An Annual Maintenance Contract is a service agreement that covers specified maintenance activities for an agreed period, typically one year. It defines the equipment covered, maintenance schedule, service scope, and applicable charges.\"},{\"question\":\"Which equipment can be covered under your AMC service?\",\"answer\":\"Depending on service availability and the agreed contract, coverage may include genset batteries, lithium-ion battery systems, vehicle batteries, and other supported battery or electrical equipment. Contact our team to confirm eligibility for your equipment.\"},{\"question\":\"What does an AMC service include?\",\"answer\":\"An AMC may include scheduled inspections, preventive maintenance, battery condition checks, connection inspections, technical support, and maintenance reporting. The exact inclusions depend on the selected plan and contract terms.\"},{\"question\":\"What are the benefits of an annual maintenance contract?\",\"answer\":\"An AMC helps organise routine maintenance, identify potential equipment issues early, plan maintenance expenses, and reduce the risk of avoidable breakdowns. Actual results depend on equipment condition, usage, and maintenance requirements.\"},{\"question\":\"How often will maintenance be performed under an AMC?\",\"answer\":\"Maintenance frequency depends on the equipment type, operating conditions, manufacturer recommendations, and agreed contract. Visits may be scheduled monthly, quarterly, half-yearly, or annually, depending on the selected plan.\"},{\"question\":\"Does an AMC include emergency breakdown support?\",\"answer\":\"Emergency support may be included if specified in the contract. Response times, service availability, and additional charges should be confirmed before the agreement is finalised.\"},{\"question\":\"Are spare parts and battery replacements included in the AMC?\",\"answer\":\"Spare parts, consumables, battery replacements, and major repairs are included only if specifically stated in the agreement. Our team can clarify the coverage and any additional charges before contract confirmation.\"},{\"question\":\"How can I request an AMC quotation?\",\"answer\":\"Contact our team with your equipment details, quantity, location, maintenance history, and service requirements. We can assess your needs and provide a suitable AMC proposal based on the agreed scope.\"},{\"question\":\"Can I renew my annual maintenance contract?\",\"answer\":\"Yes, renewal may be arranged before the existing contract expires, subject to service availability and mutually agreed renewal terms. An equipment review can help determine any changes needed for the next contract period.\"}]', 'active', 0, 1, NOW());